CUPTI_INCLUDE= CUPTI_LIB=
for dir in "$CUDA_ROOT/extras/CUPTI/include" "$CUDA_ROOT/include" "$CUDA_ROOT/targets/x86_64-linux/include"; do
  if [[ -f $dir/cupti.h ]]; then CUPTI_INCLUDE="$dir"; break; fi
